@js:
data=result.match(/data:\s*'(.*?)'/)[1];
nonce=result.match(/<script>window.*?=(.*?)<\/script>/)[1];
nonce=eval(nonce);
var N = String(nonce).match(/\d+\w+/);
jlen=N.length;
while(jlen){
jlen -= 1;
jlocate = parseInt(N[jlen].match(/(\d+)/)[0]) &255;
jstr = N[jlen].replace(/\d+/g,'');
data=data.substring(0,parseInt(jlocate))+data.substring(parseInt(jlocate)+jstr.length,data.length)}
piclist=eval(java.base64Decode(data).match(/"picture":(\[{".*\])/)[1]);
html='';
for(i in piclist){
html += '<img src="'+piclist[i].url+'">\n'
}
html

ruleSearchList:
$.[*]
<js>
var opts = {
  pattern: /\/show\/1\/([^\/]+)\//,
  name: '$.title',
  author: '$.authors'
};

//删除糢糊匹配的搜索结果，然后按书名长度排序。依赖于baseUrl、result变量。
//return Array
//opts Object: 参数，包含以下key：
//target List<Object>(result): 要过滤列表。
//pattern RegExp: 匹配searchKey的正则表达式。
//name String: 书名规则。
//author String: 作者规则。
//charset String('UTF-8'): 编码方式。
//sorting Boolean(true): 是否重新排序。

function searchFilter(opts){
  result = opts.target === undefined ? result : opts.target;
  opts.charset = opts.charset === undefined ? 'UTF-8' : opts.charset;
  opts.sorting = opts.sorting === undefined ? true : !!opts.sorting;
  function getText(ele, rule){
    java.setContent(ele);
    return String(java.getString(rule));
  }
  try {
    var kw = (baseUrl.match(opts.pattern) || ['',''])[1];
    kw = Packages.java.net.URLDecoder.decode(kw, opts.charset);
    result = result.toArray().filter(e => getText(e, opts.name).includes(kw) || getText(e, opts.author).includes(kw));
    return opts.sorting ? result.sort((a, b) => getText(a, opts.name).length - getText(b, opts.name).length) : result;
  } catch(e) {
    return result;
  }
}

searchFilter(opts);
</js>

ruleChapterList:
+<js>
//二级目录，Json
var jdoc = JSON.parse(result);
var chUrl = 'https://v3api.dmzj.com/novel/download/@get:{ID}_';
var volUrl = 'https://translate.google.cn/#view=home&op=translate&sl=zh-CN&tl=en&text=';
var list = [];

function format(title){
  return title.trim().replace(/^(\d+)(?![\s\d卷部章节回.])/, '$1 ').replace(/\s+/g, "\x20\x20");
}

jdoc.forEach((vol,idx) => {
  var chs = vol.chapters.map(ch => ({
    text: (ch.IsVip === '1' ? '💰' : '').padStart(4, "\u2000") + format(ch.chapter_name),
    href: chUrl+vol.volume_id+'_'+ch.chapter_id+'.txt',
    name: format(ch.chapter_name)
  }));

  var volInfo = '目录(' + chs.length + ")：\n";
  volInfo += chs.slice(0,10).map(v => v.name).join("\n");
  volInfo += chs.length > 10 ? "\n……" : '';
  list.push({
    text: '🔻[ ' + format(vol.volume_name) + ' ]',
    href: volUrl + encodeURIComponent(volInfo)
  });
  list = list.concat(chs);
});

result = list;
</js>

ruleContent.payAction:
// 解密
let key = java.base64DecodeToByteArray("lXsAUe1NZEw6tAxM9w1Tpq2tU4la2+PwM8evj2C+yB0=")
let iv = java.base64DecodeToByteArray("AAAAAAAAAAAAAAAAAAAAAA==")
let aes = Packages.cn.hutool.crypto.symmetric.AES("CBC","PKCS5Padding", key, iv)
// 参数
let headerMap = source.getLoginHeaderMap()
let app_version = headerMap['app_version']
let account = headerMap['account']
let login_token = headerMap['login_token']
let device_token = headerMap['device_token']
let shelf_id = headerMap['shelf_id']
let chapter_id = chapter.url.match(/chapter_id=(\d+)/)[1]
let params = `app_version=${app_version}&device_token=${device_token}&login_token=${login_token}&account=${account}`
// 开始购买
let payUrl = `https://sk.hbooker.com/chapter/buy?${params}&shelf_id=${shelf_id}&chapter_id=${chapter_id}`
let payRes = JSON.parse(aes.decryptStr(java.ajax(payUrl)))
if(payRes.tip){
 java.toast(payRes.tip)
 throw new Error(payRes.tip)	
}
// 更新书币
let propUrl = `https://sk.hbooker.com/reader/get_prop_info?${params}`
let propRes = JSON.parse(aes.decryptStr(java.ajax(propUrl)))
if(propRes.tip){
 java.toast(propRes.tip)
 throw new Error(propRes.tip)	
}
let rest_hlb = propRes.data.prop_info.rest_hlb
java.toast(`购买成功,剩余书币${rest_hlb},请手动刷新正文`)
source.putLoginHeader(Object.assign(headerMap,{'rest_hlb': String(rest_hlb)}))

